// Free times for the next 30 days, read from each clinic's own booking system.
// Live appointment times come from the availability checker, which reads each
// clinic's booking system 4 times a day: github.com/zakariyaicloud-spec/Boxing-availability
var AVAIL_URL = 'https://raw.githubusercontent.com/zakariyaicloud-spec/Boxing-availability/main/availability.json';
var STALE_HOURS = 12; // times older than this are hidden and the clinic switches to "request a time"
var DOW=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'], MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function dayLabel(iso){var d=new Date(iso+'T12:00:00');return DOW[d.getDay()]+' '+d.getDate()+' '+MON[d.getMonth()]}
var TODAY=(function(){var d=new Date();return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)})();
function nextWeekdays(n){var o=[],d=new Date();d.setHours(12);while(o.length<n){d.setDate(d.getDate()+1);if(d.getDay()>0&&d.getDay()<6)o.push(DOW[d.getDay()]+' '+d.getDate()+' '+MON[d.getMonth()])}return o}
function nextWeekends(n){var o=[],d=new Date();d.setHours(12);while(o.length<n){d.setDate(d.getDate()+1);if(d.getDay()===0||d.getDay()===6)o.push(DOW[d.getDay()]+' '+d.getDate()+' '+MON[d.getMonth()])}return o}
function nowTime(){var d=new Date();return ('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2)}
function checkedLabel(iso){var d=new Date(iso);return d.getDate()+' '+MON[d.getMonth()]+', '+('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2)}
// Fill each clinic's days from the live file (or none), and set up "request a time" where there are none.
// Clinics whose live times we don't show: boxers request a day instead.
var LIVE_OFF=['Dr4D4 Medical'];
function applyAvailability(live){
  var clinics=(live&&live.clinics)||{}, now=Date.now(), t=nowTime();
  CLINICS.forEach(function(c){
    var a=LIVE_OFF.indexOf(c.business)===-1?clinics[c.id]:null; c.days=[]; c.checked=null;
    if(a&&a.checked&&(now-new Date(a.checked).getTime())<STALE_HOURS*3600000){
      c.days=Object.keys(a.days||{}).sort().filter(function(iso){return iso>=TODAY}).map(function(iso){
        return {label:dayLabel(iso),iso:iso,times:a.days[iso].filter(function(tm){return iso>TODAY||tm>t})};
      }).filter(function(d){return d.times.length});
      if(c.days.length) c.checked=checkedLabel(a.checked);
    }
    if(!c.days.length){
      if(!c.reqDays) c.reqDays=c.weekendOnly?nextWeekends(4):nextWeekdays(5);
      if(!c.requestNote) c.requestNote='Pick a day and we\'ll ask the clinic for you.';
    }
  });
}
applyAvailability(null);
// Load the latest times, then call done() so the page can redraw.
function loadAvailability(done){
  if(!window.fetch) return;
  var get=function(u){return fetch(u,{cache:'no-store'}).then(function(r){return r.ok?r.json():null})};
  // Live file from GitHub; if that can't be reached, try a copy next to the page (used for previews).
  get(AVAIL_URL+'?t='+Math.floor(Date.now()/600000)).catch(function(){return null}).then(function(j){return j||get('availability.json').catch(function(){return null})}).then(function(j){
    if(j){applyAvailability(j);if(done)done()}
  });
}
