function localGeo(pc){
  var out=pc.length>4&&/\d[A-Z]{2}$/.test(pc)?pc.slice(0,-3):pc;
  if(OUTCODES[out])return OUTCODES[out];
  var m=out.match(/^([A-Z]{1,2})(\d+)/);
  if(m&&OUTCODES[m[1]+m[2]])return OUTCODES[m[1]+m[2]];
  var a=out.match(/^[A-Z]{1,2}/);
  return a&&PC_AREAS[a[0]]?PC_AREAS[a[0]]:null;
}
// Turns a postcode, district or town into [lat, lon]. Resolves to null if it can't be found.
function geocode(raw){
  var pc=raw.replace(/\s+/g,'').toUpperCase(), url;
  var isFull=/^[A-Z]{1,2}\d[A-Z\d]?\d[A-Z]{2}$/.test(pc), isOut=/^[A-Z]{1,2}\d[A-Z\d]?$/.test(pc);
  if(isFull) url='https://api.postcodes.io/postcodes/'+pc;
  else if(isOut) url='https://api.postcodes.io/outcodes/'+pc;
  else url='https://api.postcodes.io/places?limit=1&q='+encodeURIComponent(raw.trim());
  var timeout=new Promise(function(_,rej){setTimeout(function(){rej(new Error('timeout'))},4000)});
  return Promise.race([fetch(url).then(function(r){return r.json()}),timeout]).then(function(j){
    var res=Array.isArray(j.result)?j.result[0]:j.result;
    if(res&&res.latitude!=null)return [res.latitude,res.longitude];
    return (isFull||isOut)?localGeo(pc):null;
  }).catch(function(){return (isFull||isOut)?localGeo(pc):null});
}

